import {missingCases,createMissing,missingModel,changeMissing,missingExample} from './missing-ribbon-core.mjs';
import {missingCopy as copy,missingJobs,missingKnownNumerator,missingUnmatched,missingMatched,missingWhole,missingPartial,missingCompletion,missingReference} from './missing-ribbon-content.mjs';
import {commonRibbonArt} from './common-cuts-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const createMissingView=()=>({caseId:null,cases:new Map(),reference:false,example:false,frame:0,panels:{}});
export function startMissingCase(v,id){
 if(!missingJobs[id])return false;
 if(!v.cases.has(id)){const state=createMissing(id);if(!state)return false;v.cases.set(id,state);}
 v.caseId=id;v.reference=false;v.example=false;v.frame=0;v.panels.chooser=false;return true;
}
const button=(action,label,disabled=false,factor)=>`<button type="button" data-missing-action="${action}"${factor?` data-missing-factor="${factor}"`:''}${disabled?' disabled':''}>${esc(label)}</button>`;
const catalog=v=>`<div class="missing-catalog">${missingCases.map(c=>`<button type="button" data-missing-start="${c.id}"${v.caseId===c.id?' aria-current="true"':''} data-join-read>${esc(missingJobs[c.id].title)} — Total ${c.totalNumerator}/${c.totalDenominator}; known A ${c.knownNumerator}/${c.knownDenominator}.</button>`).join('')}</div>`;
const neutral=n=>Array.from({length:n},()=>({neutral:true}));
function lengthArt(strip,n,d,id,label){return Array.from({length:n>d?2:1},(_,i)=>strip(d,neutral(Math.max(0,Math.min(d,n-i*d))),`${id}-${i}`,`${label}; strip ${i+1}, ${Math.max(0,Math.min(d,n-i*d))} pieces of size 1/${d}.`)).join('');}
function materials(m,strip,example=false){
 const prefix=example?'missing-example':'missing-live',locked=m.removed>0;
 const totalLabel=`Given total: ${m.originalTotalNumerator}/${m.originalTotalDenominator}. Now named ${m.totalNumerator}/${m.totalDenominator}.`;
 const knownLabel=`Known length A: ${m.known.originalNumerator}/${m.known.originalDenominator}. Now named ${missingKnownNumerator(m)}/${m.known.denominator}.`;
 return `<div class="missing-references"><section class="missing-total" data-missing-role="total" data-missing-count="${m.totalNumerator}" data-missing-denominator="${m.totalDenominator}"><h3 data-join-read>Given total</h3><p data-join-read>${totalLabel}</p>${lengthArt(strip,m.totalNumerator,m.totalDenominator,prefix+'-total',totalLabel)}${missingWhole(m.totalNumerator,m.totalDenominator)?`<p data-join-read>${missingWhole(m.totalNumerator,m.totalDenominator)}</p>`:''}${example?'':`<div class="missing-actions">${button('split-total','Split total pieces in 2',locked||!m.canSplitTotal,2)}${button('uncut-total','Undo total cut',locked||!m.canUndoTotal)}</div>`}</section><section class="missing-known" data-missing-role="known" data-missing-count="${m.known.numerator}" data-missing-denominator="${m.known.denominator}"><h3 data-join-read>Known length A</h3><p data-join-read>${knownLabel}</p>${commonRibbonArt(m.known,'left',prefix)}${example?'':`<div class="missing-actions">${button('split-known','Split A pieces in 2',locked||!m.canSplitKnown2,2)}${button('split-known','Split A pieces in 3',locked||!m.canSplitKnown3,3)}${button('uncut-known','Undo A cut',locked||!m.canUndoKnown)}</div>`}</section></div><div class="missing-material"><section class="missing-remaining" data-missing-role="remaining" data-missing-count="${m.remaining}" data-missing-denominator="${m.totalDenominator}"><h3 data-join-read>Remaining length</h3>${lengthArt(strip,m.remaining,m.totalDenominator,prefix+'-remaining','Remaining length')}${missingWhole(m.remaining,m.totalDenominator)?`<p data-join-read>${missingWhole(m.remaining,m.totalDenominator)}</p>`:''}${example?'':`<div class="missing-actions">${button('take','Set aside one piece',!m.canTake)}${button('undo','Undo last separation',!m.canUndo)}${button('return','Return all pieces',!m.canReturn)}</div>`}</section><section class="missing-set-aside" data-missing-role="aside" data-missing-count="${m.removed}" data-missing-denominator="${m.totalDenominator}"><h3 data-join-read>Set-aside length</h3>${lengthArt(strip,m.removed,m.totalDenominator,prefix+'-aside','Set-aside length')}<p data-join-read>${m.removed}/${m.totalDenominator} set aside.</p></section></div>`;
}
const panel=(v,key,title,text)=>`<details data-join-panel="${key}"${v.panels[key]?' open':''}><summary>${title}</summary><p data-join-read>${text}</p></details>`;
function example(v,strip){const m=missingExample(v.frame);return `<div data-missing-view="example" data-missing-frame="${v.frame}"><h2 id="join-heading" tabindex="-1" data-join-read>Show me with quarters</h2><p data-join-read>These are separate example ribbons. Your ribbons stay as you left them.</p><p data-join-read>${copy.whole}</p>${materials(m,strip,true)}${v.frame===4?`<section class="missing-claim" data-missing-role="claim" data-missing-denominator="2"><h3 data-join-read>Different claim: 2/2</h3>${lengthArt(strip,2,2,'missing-claim','Different claim: 2/2 of the same whole')}</section>`:''}<p class="missing-caption" data-join-read role="status">Picture ${v.frame+1} of 5. ${copy.frames[v.frame]}</p><nav class="missing-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===4)}${button('back','Back to my ribbons')}</nav>${hearButton('','Hear this picture')}</div>`;}
function board(v,strip){const m=missingModel(v.cases.get(v.caseId));if(!m)return '';return `<div data-missing-view="case" data-missing-case="${v.caseId}" data-missing-complete="${m.complete}"><h2 id="join-heading" tabindex="-1" data-join-read>${esc(missingJobs[v.caseId].title)}</h2><p class="missing-request" data-join-read>${missingJobs[v.caseId].request}</p><p data-join-read>${copy.introduction}</p><p data-join-read>${copy.whole}</p><p class="missing-stage" data-join-read>${m.complete?'The set-aside length matches A. Undo a separation or return all pieces to try another way.':m.matched?missingMatched(m):missingUnmatched(m)}</p>${materials(m,strip)}<p data-join-read role="status">${m.complete?missingCompletion(m):missingPartial(m)}</p>${m.removed?`<p data-join-read>${copy.locked}</p>`:'<p data-join-read>Cuts can make at most 12 equal pieces in a whole. Undo a cut to try another way.</p>'}<div class="missing-actions">${button('reference','See the difference')}${button('example','Show me with quarters')}${hearButton('','Hear this table')}</div>${v.reference?`<p class="missing-reference" id="missing-reference" data-missing-reference tabindex="-1" data-join-read>${missingReference(m)}</p>`:''}<details data-join-panel="chooser"${v.panels.chooser?' open':''}><summary>Choose another card</summary>${catalog(v)}</details>${panel(v,'talk','Talk together',copy.talk)}</div>`;}
export function missingRibbonView(v,strip){return `<div class="missing-board" data-missing-root>${v.example?example(v,strip):v.caseId?board(v,strip):`<div data-missing-view="chooser"><h2 id="join-heading" tabindex="-1" data-join-read>${copy.title}</h2><p data-join-read>${copy.chooser}</p>${catalog(v)}</div>`}</div>`;}
export function bindMissingRibbon(root,v,{accepts,redraw,stop}){
 root.querySelectorAll('[data-missing-start]').forEach(b=>b.addEventListener('click',()=>{if(!accepts(b)||!missingJobs[b.dataset.missingStart])return;stop();if(startMissingCase(v,b.dataset.missingStart))redraw();}));
 root.querySelectorAll('[data-missing-action]').forEach(b=>b.addEventListener('click',()=>{
  if(!accepts(b))return;const action=b.dataset.missingAction;
  if(action==='example'){stop();v.example=true;v.reference=false;v.frame=0;redraw();return;}
  if(action==='back'&&v.example){stop();v.example=false;v.frame=0;redraw('[data-missing-action="example"]');return;}
  if(['previous','next'].includes(action)&&v.example){const frame=v.frame+(action==='next'?1:-1);if(!missingExample(frame))return;stop();v.frame=frame;redraw(`[data-missing-action="${frame===4?'previous':frame===0?'next':action}"]`);return;}
  if(v.example)return;
  if(action==='reference'){stop();v.reference=true;redraw('#missing-reference');return;}
  const next=changeMissing(v.cases.get(v.caseId),action,b.dataset.missingFactor===undefined?undefined:Number(b.dataset.missingFactor));if(!next)return;
  stop();v.cases.set(v.caseId,next);v.reference=false;
  const selector=`[data-missing-action="${action}"]${b.dataset.missingFactor?`[data-missing-factor="${b.dataset.missingFactor}"]`:''}`;
  const fallback=action==='take'?'[data-missing-action="undo"]':action==='undo'||action==='return'?'[data-missing-action="take"]':action==='split-known'?'[data-missing-action="uncut-known"]':action==='split-total'?'[data-missing-action="uncut-total"]':'#join-heading';
  redraw(selector,fallback);
 }));
}
